declare(strict_types=1);
session_start();$root=dirname(__DIR__,3);$cfg=require $root.'/config.php';date_default_timezone_set($cfg['timezone']??'America/Argentina/Buenos_Aires');$db=new PDO('mysql:host='.$cfg['db_host'].';dbname='.$cfg['db_name'].';charset=utf8mb4',$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);if(empty($_SESSION['user'])){header('Location:index.php');exit;}
function e4($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function usd4($n):string{return 'US$ '.number_format((float)$n,2,',','.');}function img4($data,$mime):string{return(!empty($data)&&!empty($mime))?'data:'.$mime.';base64,'.base64_encode($data):'';}function tax4(float $b,string $m,float $v):float{return$m==='mas_iva'?round($b*(1+$v/100),2):$b;}function fam4(string $v):string{$v=strtolower(str_replace([' ','-','_'],'',trim($v)));if(in_array($v,['lifesmart','lifemar','lightsmart'],true))return'lifesmart';if(in_array($v,['control4','controlfour'],true))return'control4';if(in_array($v,['shelly','shelley'],true))return'shelly';return'';}function remote4(string $url):string{$d=false;$t='image/png';if(function_exists('curl_init')){$c=curl_init($url);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_TIMEOUT=>8,CURLOPT_CONNECTTIMEOUT=>4,CURLOPT_USERAGENT=>'PuntoERP/1.0']);$d=curl_exec($c);$code=(int)curl_getinfo($c,CURLINFO_HTTP_CODE);$ct=(string)curl_getinfo($c,CURLINFO_CONTENT_TYPE);curl_close($c);if($code<200||$code>=300)$d=false;if($ct)$t=$ct;}if($d===false)$d=@file_get_contents($url);return($d!==false&&$d!=='')?'data:'.$t.';base64,'.base64_encode($d):'';}
$id=(int)($_GET['id']??0);$s=$db->prepare("SELECT q.*,p.project_number,p.name project_name,p.engineering_pct,c.business_name,c.contact_name,c.cuit,c.email,c.whatsapp,c.address,c.city,c.province,pp.business_name partner_name,pl.name price_list_name FROM quotes q JOIN projects p ON p.id=q.project_id JOIN clients c ON c.id=p.client_id LEFT JOIN project_partners pp ON pp.id=p.partner_id LEFT JOIN price_lists pl ON pl.id=q.price_list_id WHERE q.id=?");$s->execute([$id]);$q=$s->fetch();if(!$q)exit('Presupuesto inexistente.');
$s=$db->prepare("SELECT qi.*,p.image_data,p.image_mime FROM quote_items qi LEFT JOIN products p ON p.id=qi.product_id WHERE qi.quote_id=? ORDER BY qi.block_order,qi.sort_order,qi.id");$s->execute([$id]);$items=$s->fetchAll();$laborRows=[];try{$s=$db->prepare('SELECT * FROM quote_labor_items WHERE quote_id=? ORDER BY block_order,id');$s->execute([$id]);$laborRows=$s->fetchAll();}catch(Throwable $x){}
$blocks=[];$maxOrder=0;foreach($items as $it){$o=(int)($it['block_order']??0);$maxOrder=max($maxOrder,$o);if(!isset($blocks[$o]))$blocks[$o]=['type'=>'materials','title'=>$it['section_title']?:'Materiales','items'=>[],'subtotal'=>0];$blocks[$o]['items'][]=$it;$blocks[$o]['subtotal']+=(float)$it['subtotal'];}foreach($laborRows as $li){$o=(int)$li['block_order'];$maxOrder=max($maxOrder,$o);$blocks[$o]=['type'=>'labor','title'=>$li['title'],'description'=>$li['description'],'amount'=>(float)$li['amount'],'tax_mode'=>$li['tax_mode'],'vat_rate'=>(float)$li['vat_rate']];}if(!$laborRows&&(float)$q['labor_amount']>0)$blocks[$maxOrder+10]=['type'=>'labor','title'=>'Mano de obra','description'=>$q['labor_description']?:'Configuración, montaje y diseño de escenas','amount'=>(float)$q['labor_amount'],'tax_mode'=>$q['labor_tax_mode']??'sin_iva','vat_rate'=>(float)($q['labor_vat_rate']??21)];ksort($blocks);
$logo=remote4('https://puntodomotica.com/assets/images/cropped-logo-blanco-63892739ae.png');$families=array_filter(array_map('trim',explode(',',(string)($q['quote_families']??''))));$src=(string)($q['quote_template_family']??'');if($src===''&&!empty($families))$src=(string)$families[0];$template=fam4($src);$familyLabel=['lifesmart'=>'LifeSmart','control4'=>'Control4','shelly'=>'Shelly'][$template]??'Sin definir';$mat=(float)$q['materials_amount'];$matMode=(string)($q['materials_tax_mode']??'mas_iva');$matVat=(float)($q['materials_vat_rate']??21);$matTotal=tax4($mat,$matMode,$matVat);$lab=(float)$q['labor_amount'];$labTotal=0;foreach($blocks as $b)if($b['type']==='labor')$labTotal+=tax4((float)$b['amount'],(string)$b['tax_mode'],(float)$b['vat_rate']);$total=(float)$q['total'];
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Presupuesto <?=e4($q['project_number'])?></title><style>@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;background:#e8e8e8;color:#202124;font-family:Aptos,"Segoe UI",Arial,sans-serif;font-size:12px}.toolbar{width:210mm;margin:12px auto;display:flex;gap:8px}.toolbar a,.toolbar button{border:0;border-radius:7px;padding:10px 14px;background:#ff6702;color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.toolbar .dark{background:#242122}.toolbar .light{background:#fff;color:#242122;border:1px solid #d4d4d4}.sheet{position:relative;width:210mm;min-height:297mm;margin:0 auto 20px;background:#fff;overflow:hidden;box-shadow:0 12px 34px #0002}.top-art{position:absolute;left:0;top:0;width:155mm;height:48mm;z-index:1}.header{position:relative;z-index:3;height:42mm}.logo{position:absolute;left:13mm;top:8mm;width:54mm}.titlebox{position:absolute;right:14mm;top:11mm;text-align:right}.titlebox h1{margin:0;color:#ff6702;font-size:29px;font-weight:600}.titlebox .code{margin-top:3mm;font-size:10.5px;color:#45515d}.meta-strip{position:relative;z-index:4;display:grid;grid-template-columns:1.1fr .56fr 1.22fr .72fr 1.12fr .7fr;padding:0 14mm 6mm 24mm}.meta-item{padding:0 5mm;border-left:1.5px solid #ff6702}.meta-item:first-child{border-left:0;padding-left:0}.meta-item .k{display:block;font-weight:700;font-size:10.5px;margin-bottom:1mm}.meta-item .v{display:block;color:#33404b;font-size:10.7px}.meta-item .main{font-size:11.4px;font-weight:700;color:#202124}.tablewrap{padding:0 14mm}.equipment{width:100%;border-collapse:collapse;table-layout:fixed}.equipment th{background:#ff6702;color:#fff;height:10mm;padding:0 3mm;text-align:left;font-size:10.5px}.equipment td{border-bottom:1px solid #d7d7d7;padding:2.3mm 3mm;vertical-align:middle;font-size:10.8px}.equipment .pic{width:14mm;text-align:center}.equipment .pic img{max-width:11mm;max-height:11mm;object-fit:contain}.equipment .sku{width:25mm;font-weight:700;font-size:9.8px}.equipment .qty{width:15mm;text-align:center}.equipment .price{width:25mm;text-align:right}.equipment .subtotal{width:27mm;text-align:right;font-weight:700}.section-title td{background:#f3f3f3!important;font-weight:800;font-size:11.5px;border-top:1.5px solid #bfc3c7}.section-title .section-total{text-align:right;color:#202124}.labor-row td{background:#fff}.labor-row .labor-desc{padding-left:8mm}.summarywrap{display:grid;grid-template-columns:1fr 72mm;gap:14mm;margin:8mm 14mm 27mm}.notes h3{margin:0 0 3mm;color:#ff6702}.notes p{white-space:pre-line;color:#4f565d}.summary .r{display:flex;justify-content:space-between;padding:2.4mm 0}.summary .grand{border-top:1px solid #333;margin-top:3mm;padding-top:4mm;color:#ff6702;font-size:19px;font-weight:700}.footerbrand{position:absolute;left:14mm;bottom:10mm;color:#ff6702;font-weight:700}.footnote{position:absolute;right:14mm;bottom:10mm;text-align:right;font-size:9.5px;color:#4d4d4d}.bottom-art{position:absolute;right:0;bottom:0;width:82mm;height:25mm}.screen-note{width:210mm;margin:0 auto 18px;background:#fff;border:1px solid #ddd;padding:10px 14px;font-size:12px}</style><script src="https://cdn.jsdelivr.net/npm/html2canvas@1.4.1/dist/html2canvas.min.js"></script><script src="https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js"></script></head><body><div class="toolbar"><a class="light" href="?a=quotes">← Presupuestos</a><a class="dark" href="?a=edit_quote&id=<?=$id?>">Editar</a><button id="generatePdfBtn" type="button" onclick="generatePdf()">Generar PDF</button></div><section class="sheet" id="quoteSheet"><svg class="top-art" viewBox="0 0 600 185" preserveAspectRatio="none"><polygon fill="#f2f2f2" points="0,112 405,52 245,111 0,185"/><polygon fill="#242122" points="0,0 600,0 96,145 0,157"/><polygon fill="#ff6702" points="0,0 202,0 78,87 0,116"/></svg><header class="header"><?php if($logo):?><img class="logo" src="<?=$logo?>" alt="Punto Domótica"><?php endif;?><div class="titlebox"><h1>PRESUPUESTO</h1><div class="code"><?=e4($q['project_number'])?> · v<?=e4($q['version_no'])?></div></div></header><div class="meta-strip"><div class="meta-item"><span class="k">Cliente</span><span class="v main"><?=e4($q['business_name'])?></span></div><div class="meta-item"><span class="k">Proyecto</span><span class="v"><?=e4($q['project_number'])?></span></div><div class="meta-item"><span class="k">Obra</span><span class="v"><?=e4($q['project_name'])?></span></div><div class="meta-item"><span class="k">Fecha</span><span class="v"><?=e4(date('d/m/Y',strtotime($q['quote_date'])))?></span></div><div class="meta-item"><span class="k">Arquitecto</span><span class="v"><?=e4($q['partner_name']?:'—')?></span></div><div class="meta-item"><span class="k">Tecnología</span><span class="v"><?=e4($familyLabel)?></span></div></div><div class="tablewrap"><table class="equipment"><thead><tr><th class="pic">Imagen</th><th class="sku">SKU</th><th>Descripción</th><th class="qty">Cant.</th><th class="price">Precio</th><th class="subtotal">Total</th></tr></thead><tbody><?php foreach($blocks as $b):if($b['type']==='materials'):?><tr class="section-title"><td colspan="5"><?=e4($b['title'])?></td><td class="section-total"><?=usd4($b['subtotal'])?></td></tr><?php foreach($b['items'] as $it):$im=img4($it['image_data']??null,$it['image_mime']??null);?><tr><td class="pic"><?php if($im):?><img src="<?=$im?>" alt=""><?php endif;?></td><td class="sku"><?=e4($it['sku']?:'—')?></td><td><?=e4($it['description'])?></td><td class="qty"><?=e4(rtrim(rtrim(number_format((float)$it['quantity'],2,'.',''),'0'),'.'))?></td><td class="price"><?=usd4($it['unit_price'])?></td><td class="subtotal"><?=usd4($it['subtotal'])?></td></tr><?php endforeach;else:?><tr class="section-title"><td colspan="5"><?=e4($b['title'])?></td><td class="section-total"><?=usd4($b['amount'])?></td></tr><tr class="labor-row"><td></td><td colspan="4" class="labor-desc"><?=e4($b['description'])?></td><td class="subtotal"><?=usd4($b['amount'])?></td></tr><?php endif;endforeach;?></tbody></table></div><div class="summarywrap"><div class="notes"><?php if(trim((string)$q['notes'])!==''):?><h3>Observaciones</h3><p><?=e4($q['notes'])?></p><?php endif;?></div><div class="summary"><div class="r"><span><?=$matMode==='mas_iva'?'Materiales + IVA':($matMode==='iva_incluido'?'Materiales (IVA incluido)':'Materiales')?></span><b><?=usd4($matTotal)?></b></div><?php if($lab>0):?><div class="r"><span>Mano de obra</span><b><?=usd4($labTotal)?></b></div><?php endif;?><div class="r grand"><span>TOTAL</span><span><?=usd4($total)?></span></div></div></div><div class="footerbrand">Punto Domótica<div style="color:#444;font-weight:400;font-size:9.5px">Espacios inteligentes</div></div><div class="footnote">Valores expresados en dólares estadounidenses (USD)<br>Presupuesto <?=e4($q['project_number'])?> · versión <?=e4($q['version_no'])?></div><svg class="bottom-art" viewBox="0 0 310 95" preserveAspectRatio="none"><polygon fill="#242122" points="125,95 310,15 310,95"/><polygon fill="#ff6702" points="235,95 310,48 310,95"/></svg></section><div class="screen-note">El PDF final se genera en este orden: <b>prólogo <?=e4($familyLabel)?> → presupuesto → forma de pago</b>.</div><script>const quoteFamily=<?=json_encode($template,JSON_UNESCAPED_SLASHES)?>,familyLabel=<?=json_encode($familyLabel,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,pdfFilename=<?=json_encode('Presupuesto-'.$q['project_number'].'-v'.$q['version_no'].'.pdf',JSON_UNESCAPED_SLASHES)?>,prologueUrl='?a=quote_pdf_asset&type=prologo&family='+encodeURIComponent(quoteFamily),paymentUrl='?a=quote_pdf_asset&type=pago&family='+encodeURIComponent(quoteFamily);async function waitForImages(r){await Promise.all([...r.querySelectorAll('img')].map(i=>i.complete&&i.naturalWidth?Promise.resolve():new Promise(x=>{i.addEventListener('load',x,{once:true});i.addEventListener('error',x,{once:true});setTimeout(x,5000)})))}async function quotePdf(){const s=document.getElementById('quoteSheet');await waitForImages(s);const c=await html2canvas(s,{scale:2,useCORS:true,backgroundColor:'#fff',logging:false,width:s.scrollWidth,height:s.scrollHeight,windowWidth:s.scrollWidth,windowHeight:s.scrollHeight});const p=await PDFLib.PDFDocument.create(),png=await p.embedPng(c.toDataURL('image/png')),pw=595.28,ph=841.89,sc=Math.min(pw/png.width,ph/png.height),w=png.width*sc,h=png.height*sc,page=p.addPage([pw,ph]);page.drawImage(png,{x:(pw-w)/2,y:ph-h,width:w,height:h});return p}async function append(target,url,required,label){const r=await fetch(url,{cache:'no-store'});if(!r.ok){if(required)throw new Error('Falta '+label+'. Cargalo en Presupuestos → Archivos PDF.');return}const src=await PDFLib.PDFDocument.load(await r.arrayBuffer()),pages=await target.copyPages(src,src.getPageIndices());pages.forEach(p=>target.addPage(p))}async function generatePdf(){const b=document.getElementById('generatePdfBtn'),old=b.textContent;b.disabled=true;b.textContent='Generando PDF...';try{if(!quoteFamily)throw new Error('El presupuesto no tiene definida la familia principal.');const qp=await quotePdf(),final=await PDFLib.PDFDocument.create();await append(final,prologueUrl,true,'el prólogo de '+familyLabel);(await final.copyPages(qp,qp.getPageIndices())).forEach(p=>final.addPage(p));await append(final,paymentUrl,true,'la forma de pago de '+familyLabel);const bytes=await final.save(),blob=new Blob([bytes],{type:'application/pdf'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=pdfFilename;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1500)}catch(err){alert('No pude generar el PDF final. '+(err?.message||''))}finally{b.disabled=false;b.textContent=old}}</script></body></html>